/**
 * The platform's ACTION vocabulary — what may be done to a record.
 *
 * DUPLICATED from `packages/carbon/src/consts/permissions.ts` on purpose: this
 * package is published standalone and must not depend on carbon, and no generated
 * model carries these (network's `Permission` is a different thing — the
 * `{name, displayName}` record inside a permission GROUP). Carbon is the source of
 * truth; if it gains a value, add it here too.
 *
 * `ALL` is a wildcard that satisfies every check, which is not guessable and is why
 * callers should never hand-roll the comparison.
 */
declare const Permission: {
    readonly ALL: "ALL";
    readonly READ: "READ";
    readonly CREATE: "CREATE";
    readonly EDIT: "EDIT";
    readonly DELETE: "DELETE";
    readonly CLONE: "CLONE";
    readonly DEPLOY: "DEPLOY";
    readonly EXECUTE: "EXECUTE";
    readonly EXPORT: "EXPORT";
    readonly IMPORT: "IMPORT";
    readonly APPROVE: "APPROVE";
    readonly TEST: "TEST";
    readonly VIEW_RUNS: "VIEW_RUNS";
};
/**
 * A permission name. The constants above cover the platform's own entity types; a
 * custom entity type may define its own names, so a bare string is accepted rather
 * than refused — a name that does not exist simply never matches.
 */
type PermissionName = (typeof Permission)[keyof typeof Permission] | (string & {});
interface RecordAccess {
    canAccess: boolean;
    /** False once the lookup has settled — including when it never ran (disabled). */
    isLoading: boolean;
}
/**
 * Does the signed-in user hold ANY of `permission` on this record?
 *
 * OR, not AND — holding any one of the names passed is enough, and `ALL` satisfies
 * everything. This is the opposite of how an interface's permission-group MAP
 * combines (there, every group and every name is required), so the two are easy to
 * reason about wrongly. Ask for the single permission the action needs.
 */
declare function hasPermissionAccess(held: readonly string[] | undefined, permission: PermissionName | PermissionName[]): boolean;
/**
 * Per-record permission check, reporting whether the answer has settled.
 *
 * Use THIS form whenever the answer picks a request — a mutation to send, a route to
 * take, a payload to build. `canAccess` is false while the lookup is in flight, and
 * a not-yet-loaded false is indistinguishable from a denial, so acting on it sends
 * the wrong request rather than none. Use `useCanAccessRecord` only to show or hide.
 *
 * Disabled or missing `entityId` reports settled (`isLoading: false`) rather than
 * loading forever, so a caller gating on it cannot hang.
 */
declare function useRecordAccess(entityId: string | undefined, entityType: string, permission: PermissionName | PermissionName[], options?: {
    enabled?: boolean;
}): RecordAccess;
/**
 * Per-record permission check as a bare boolean — false while loading.
 *
 * Only for showing or hiding, where a moment of the denied state is a flicker rather
 * than a wrong action. Anything that ACTS on the answer wants `useRecordAccess`.
 */
declare function useCanAccessRecord(entityId: string | undefined, entityType: string, permission: PermissionName | PermissionName[], options?: {
    enabled?: boolean;
}): boolean;

export { Permission, hasPermissionAccess, useCanAccessRecord, useRecordAccess };
export type { PermissionName, RecordAccess };
